mat2 Rotate2D(in float a) {
    float co = cos(a), si = sin(a);
    return mat2(co, -si, si, co);
}

// https://www.shadertoy.com/view/4djSRW
float Hash11(in float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

vec3 Hash33(in vec3 p) {
    p = fract(p * vec3(0.1031, 0.103, 0.0973));
    p += dot(p, p.yxz + 33.33);
    return fract((p.xxy + p.yxx) * p.zyx);
}

float map(in vec3 p) {
    p.y += iTime;
    float w = 4.0;
    vec3 cell = floor(p / w) * w;
    p -= cell + 0.5 * w;
    p.xz *= Rotate2D(iTime * Hash11(cell.y) * 2.0);
    p -= 2.0 * Hash33(cell) - 1.0;
    return 0.5 * (length(p) - 0.25);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;
    vec2 mouse = (iMouse.xy - 0.5 * iResolution.xy) / iResolution.y;
    vec3 color = vec3(0.0);

    vec3 ro = vec3(10.0 * mouse, 5.0);

    vec3 fd = -normalize(ro);
    vec3 rt = normalize(vec3(-fd.z, 0.0, fd.x));
    vec3 up = cross(rt, fd);

    vec3 rd = normalize(uv.x * rt + uv.y * up + fd);

    color = vec3(0.5, 0.5, 1.0) * pow(1.0 - length(fragCoord / iResolution.xy - 0.5), 0.8);
    if (rd.y < 0.0 && ro.y > -10.0) {
        color = mix(color, vec3(1.0), pow(-rd.y, 0.4));
    }

    bool inside = map(ro) < 0.0;
    float total = 0.0;
    float t = 0.0;
    for (int i=0; i < 100; i++) {
        if (inside) {
            total += 0.03;
            t += 0.02;
            if (map(ro + rd * t) >= 0.0) inside = false;
        }

        else {
            t += map(ro + rd * t);
            if (map(ro + rd * t) < 1e-3) inside = true;
        }

        if (total > 1.0 || t > 60.0 || ro.y + rd.y * t < -10.0) break;
    }

    color = mix(color, vec3(1.0), total);
    fragColor = vec4(color, 1.0);
}
